import { useEffect, useMemo, useState } from 'react';
import ReactDOM from 'react-dom/client';
import { Nav, Footer } from './shared.jsx';
import { getLocale, locHref } from './i18n.js';
import { VIDEO_CATS } from './videos-data.js';
import { PlayIcon, VideoCard, Player, ExtIcon, thumb, fold } from './video-player.jsx';
import { Band, BandHead, PageHero, Play } from './relief.jsx';
import { ALL_VIDEOS, FEATURED, GRID_VIDEOS } from './video-list.js';

// Video tutorials page. The list comes from videos-data.js (generated by ai-video-factory
// from the channel's PUBLIC videos). Thumbnails are self-hosted; the YouTube player
// (youtube-nocookie.com) is only loaded after the visitor presses play, so opening the
// page sets no cookies and sends nothing to YouTube (see public/consent.js).
const CHANNEL = 'https://www.youtube.com/@CloudNativeWorks';

const STR = {
  en: {
    title1: 'See Elchi ',
    title2: 'at work.',
    subtitle: 'Short, hands-on tutorials. Every video shows one feature working for real: the configuration, the request and its result, on screen.',
    count: (n, m) => `${n} videos · ${m} minutes`,
    channel: 'Subscribe on YouTube',
    docs: 'Read the docs',
    featured: 'Start here',
    watch: 'Watch',
    all: 'All',
    search: 'Search videos…',
    none: 'No video matches your search.',
    empty: 'Videos are on their way. Meanwhile, see them on our YouTube channel.',
    close: 'Close',
    onYoutube: 'Watch on YouTube',
    privacy: 'Plays from youtube-nocookie.com',
    play: (t) => `Play: ${t}`,
    more: 'More tutorials on the channel',
    moreText: 'New videos are added as Elchi grows. Subscribe to get them first.',
    captions: 'English audio · English and Turkish subtitles',
    playAll: 'Play all on YouTube',
  },
  tr: {
    title1: 'Elchi\'yi ',
    title2: 'iş başında görün.',
    subtitle: 'Kısa, uygulamalı eğitimler. Her video tek bir özelliği gerçekten çalışırken gösterir: yapılandırma, istek ve sonucu ekranda.',
    count: (n, m) => `${n} video · ${m} dakika`,
    channel: 'YouTube\'da abone olun',
    docs: 'Dokümanları okuyun',
    featured: 'Buradan başlayın',
    watch: 'İzle',
    all: 'Tümü',
    search: 'Videolarda ara…',
    none: 'Aramanızla eşleşen video yok.',
    empty: 'Videolar yolda. Bu arada YouTube kanalımızdan izleyebilirsiniz.',
    close: 'Kapat',
    onYoutube: 'YouTube\'da izle',
    privacy: 'youtube-nocookie.com üzerinden oynatılır',
    play: (t) => `Oynat: ${t}`,
    more: 'Kanalda daha fazla eğitim',
    moreText: 'Elchi büyüdükçe yeni videolar ekleniyor. İlk siz görmek için abone olun.',
    captions: 'İngilizce ses · İngilizce ve Türkçe altyazı',
    playAll: 'Tümünü YouTube\'da oynat',
  },
};

// schema.org graph: a CollectionPage wrapping the VideoObject list, plus a breadcrumb, so
// search engines can show the videos as video results tied to this page and publisher.
function JsonLd({ locale }) {
  const base = `https://www.elchi.io${locale === 'tr' ? '/tr' : ''}`;
  const page = `${base}/videos.html`;
  const org = { '@id': 'https://www.elchi.io/#organization' };
  const data = {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'CollectionPage',
        '@id': `${page}#page`,
        url: page,
        name: locale === 'tr' ? 'Elchi Envoy video eğitimleri' : 'Elchi Envoy video tutorials',
        inLanguage: locale,
        isPartOf: { '@id': 'https://www.elchi.io/#website' },
        publisher: org,
        mainEntity: { '@id': `${page}#videos` },
      },
      {
        '@type': 'BreadcrumbList',
        itemListElement: [
          { '@type': 'ListItem', position: 1, name: locale === 'tr' ? 'Ana Sayfa' : 'Home', item: `${base}/` },
          { '@type': 'ListItem', position: 2, name: locale === 'tr' ? 'Videolar' : 'Videos', item: page },
        ],
      },
      {
        '@type': 'ItemList',
        '@id': `${page}#videos`,
        numberOfItems: ALL_VIDEOS.length,
        itemListElement: ALL_VIDEOS.map((v, i) => ({
          '@type': 'ListItem',
          position: i + 1,
          item: {
            '@type': 'VideoObject',
            '@id': `${page}#${v.slug}`,
            name: v.title,
            description: v[locale],
            thumbnailUrl: `https://www.elchi.io${thumb(v)}`,
            // Google wants a full ISO 8601 date-time with a time zone; the data holds a day
            uploadDate: /T/.test(v.date) ? v.date : `${v.date}T12:00:00+03:00`,
            duration: `PT${Math.floor(v.seconds / 60)}M${v.seconds % 60}S`,
            ...(v.src ? { contentUrl: `https://www.elchi.io${v.src}` } : { embedUrl: `https://www.youtube.com/embed/${v.yt}` }),
            // every video has English audio (EN and TR subtitles), whatever the page locale
            inLanguage: 'en',
            publisher: org,
            url: `${page}#${v.slug}`,
          },
        })),
      },
    ],
  };
  return <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(data).replace(/</g, '\\u003c') }}/>;
}

function VideosApp() {
  const locale = getLocale();
  const t = STR[locale];
  const [cat, setCat] = useState('all');
  const [query, setQuery] = useState('');
  const [playing, setPlaying] = useState(null);

  // #<slug> opens that video (shareable links); closing clears the hash.
  useEffect(() => {
    const fromHash = () => {
      const v = ALL_VIDEOS.find((x) => x.slug === decodeURIComponent(location.hash.slice(1)));
      if (v) setPlaying(v);
    };
    fromHash();
    window.addEventListener('hashchange', fromHash);
    return () => window.removeEventListener('hashchange', fromHash);
  }, []);
  const play = (v) => { setPlaying(v); history.replaceState(null, '', `#${v.slug}`); };
  const close = useMemo(() => () => { setPlaying(null); history.replaceState(null, '', location.pathname + location.search); }, []);

  const featured = FEATURED;
  const minutes = Math.round(ALL_VIDEOS.reduce((s, v) => s + v.seconds, 0) / 60);
  const q = fold(query.trim());
  const match = (v) => (cat === 'all' || v.cat === cat) && (!q || fold(`${v.title} ${v[locale]}`).includes(q));
  const groups = VIDEO_CATS
    .map((c) => ({ ...c, items: GRID_VIDEOS.filter((v) => v.cat === c.id && match(v)) }))
    .filter((g) => g.items.length);
  const counts = Object.fromEntries(VIDEO_CATS.map((c) => [c.id, GRID_VIDEOS.filter((v) => v.cat === c.id).length]));

  const searchIcon = (
    <svg className="vid-search-ic" width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><circle cx="8" cy="8" r="5.2" fill="none" stroke="currentColor" strokeWidth="1.8"/><path d="M12 12l3.6 3.6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/></svg>
  );

  return (
    <>
      <Nav active="videos"/>
      <JsonLd locale={locale}/>

      <main className="rl">
        <PageHero
          title={<>{t.title1}{t.title2}</>}
          lede={<>
            {t.subtitle}
            {ALL_VIDEOS.length > 0 && <span className="vid-stats">{t.count(ALL_VIDEOS.length, minutes)} · {t.captions}</span>}
          </>}
          actions={<>
            <a href={`${CHANNEL}?sub_confirmation=1`} target="_blank" rel="noopener" className="rl-go">{t.channel}<ExtIcon size={16}/></a>
            <a href="/docs/" className="rl-pill">{t.docs}</a>
          </>}
        />

        {featured && (
          <Band tone="water" className="vid-featured-band">
            <div className="vid-featured">
              <button className="vid-thumb vid-thumb-big" onClick={() => play(featured)} aria-label={t.play(featured.title)}>
                <img src={thumb(featured)} alt="" decoding="async" width="960" height="540"/>
                <span className="vid-start">{t.featured}</span>
                <span className="vid-play big"><PlayIcon size={30}/></span>
                <span className="vid-dur">{featured.duration}</span>
              </button>
              <div className="vid-featured-text">
                <h2>{featured.title}</h2>
                <p>{featured[locale]}</p>
                <button type="button" className="rl-pill" onClick={() => play(featured)}>
                  <span className="rl-pill-play"><Play/></span>{t.watch}<span className="rl-pill-dur">{featured.duration}</span>
                </button>
              </div>
            </div>
          </Band>
        )}

        <Band tone="mist" className="vid-library">
          {GRID_VIDEOS.length === 0 ? (
            <p className="vid-empty">{t.empty} <a href={CHANNEL} target="_blank" rel="noopener" className="rl-link">YouTube<ExtIcon/></a></p>
          ) : (
            <>
              <div className="vid-toolbar">
                <div className="vid-chips" role="tablist">
                  <button role="tab" aria-selected={cat === 'all'} className={cat === 'all' ? 'on' : ''} onClick={() => setCat('all')}>
                    {t.all} <span>{GRID_VIDEOS.length}</span>
                  </button>
                  {VIDEO_CATS.filter((c) => counts[c.id]).map((c) => (
                    <button key={c.id} role="tab" aria-selected={cat === c.id} className={cat === c.id ? 'on' : ''} onClick={() => setCat(c.id)}>
                      {c[locale]} <span>{counts[c.id]}</span>
                    </button>
                  ))}
                </div>
                <label className="vid-search">
                  {searchIcon}
                  <input type="search" placeholder={t.search} aria-label={t.search} value={query} onChange={(e) => setQuery(e.target.value)}/>
                </label>
              </div>

              {groups.length === 0 && <p className="vid-empty">{t.none}</p>}
              {groups.map((g) => (
                <div key={g.id} className="vid-group">
                  <div className="vid-group-head">
                    <h2 className="vid-group-title">{g[locale]} <span>{g.items.length}</span></h2>
                    {g.playlist && <a className="rl-link vid-playall" href={`https://www.youtube.com/playlist?list=${g.playlist}`} target="_blank" rel="noopener">{t.playAll}<ExtIcon/></a>}
                  </div>
                  <div className="vid-grid">
                    {g.items.map((v) => <VideoCard key={v.slug} v={v} onPlay={play}/>)}
                  </div>
                </div>
              ))}
            </>
          )}
        </Band>

        <Band tone="sage" className="vid-cta">
          <BandHead h2={t.more} intro={t.moreText}/>
          <div className="rl-actions">
            <a href={`${CHANNEL}?sub_confirmation=1`} target="_blank" rel="noopener" className="rl-go">{t.channel}<ExtIcon size={16}/></a>
          </div>
        </Band>
      </main>

      {playing && <Player v={playing} onClose={close}/>}
      <Footer/>
    </>
  );
}

export const Page = VideosApp;
if (typeof document !== 'undefined') ReactDOM.createRoot(document.getElementById('root')).render(<VideosApp/>);
